// Latest state of each incident in the window. SecurityIncident appends a new
// row on every modification, so arg_max per IncidentNumber is mandatory before
// any counting.
let incidents =
    SecurityIncident
    | where TimeGenerated {TimeRange}
    | summarize arg_max(TimeGenerated, *) by IncidentNumber;
incidents
| summarize
    ['Incidents touched'] = count(),
    ['Open'] = countif(Status in~ ('New', 'Active')),
    ['Closed'] = countif(Status =~ 'Closed'),
    ['High open'] = countif(Severity =~ 'High' and Status in~ ('New', 'Active')),
    ['Unassigned open'] = countif(isempty(tostring(Owner.userPrincipalName)) and Status in~ ('New', 'Active'))

// Daily volume split by severity. A spike in one severity band is a signal;
// a uniform rise across bands usually means a new connector or a rule change.
SecurityAlert
| where TimeGenerated {TimeRange}
| summarize Alerts = count() by bin(TimeGenerated, 1d), AlertSeverity
| order by TimeGenerated asc

// Closure classification uses the Classification column, whose only values are
// TruePositive, FalsePositive, BenignPositive and Undetermined. Undetermined is
// kept separate on purpose: an untriaged incident is not a false positive.
SecurityIncident
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| where Status =~ 'Closed'
| extend Closure = iff(isempty(Classification), 'Unclassified', tostring(Classification))
| summarize Incidents = count() by Closure
| order by Incidents desc

// Tuning candidates: rules where more than 30% of closed incidents were marked
// FalsePositive, on a sample of at least 5 closures. The 5-incident gate stops a
// single noisy day from nominating a rule; both thresholds are the ones
// documented in tests/validation/performance-metrics.md.
let min_closures = 5;
let fp_rate_trigger = 30.0;
SecurityIncident
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| where Status =~ 'Closed'
| summarize
    Closed = count(),
    FalsePositive = countif(Classification =~ 'FalsePositive'),
    TruePositive = countif(Classification =~ 'TruePositive'),
    BenignPositive = countif(Classification =~ 'BenignPositive')
    by Title
| where Closed >= min_closures
| extend ['FP rate %'] = round(100.0 * FalsePositive / Closed, 1)
| where ['FP rate %'] >= fp_rate_trigger
| project Title, Closed, TruePositive, BenignPositive, FalsePositive, ['FP rate %']
| order by ['FP rate %'] desc

// Owner is a dynamic object: userPrincipalName / email / assignedTo / objectId.
// Owner.principalName does not exist and yields a blank column.
SecurityIncident
| where TimeGenerated {TimeRange}
| summarize arg_max(TimeGenerated, *) by IncidentNumber
| where Status in~ ('New', 'Active')
| extend Owner = tostring(Owner.userPrincipalName)
| project IncidentNumber, Title, Severity, Status, Owner, CreatedTime,
          ['Age (min)'] = datetime_diff('minute', now(), CreatedTime)
| order by CreatedTime desc
